import os
import random
import numpy as np
import torch

# =============================================================================
# PATH CONFIGURATION
# =============================================================================

# Base Directories
INPUT_DIR = "./input"
TRAIN_DIR = os.path.join(INPUT_DIR, "train")
TEST_DIR = os.path.join(INPUT_DIR, "test")
METADATA_DIR = "./metadata"

# Metadata Paths (Generated by the provided metadata script)
TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

# Working Directory for Caching and Models
WORKING_DIR = "./working/idea_39"
CACHE_DIR = os.path.join(WORKING_DIR, "cache")
MODEL_SAVE_DIR = os.path.join(WORKING_DIR, "models")
SUBMISSION_DIR = "./submission"
SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# =============================================================================
# DATA CONFIGURATION
# =============================================================================

# Image Parameters
IMG_SIZE = (224, 224)  # Standard input size for EfficientNet-B0
NUM_CHANNELS = 3  # Channels: FLAIR, T1wCE, T2w
INPUT_CHANNELS = ["FLAIR", "T1wCE", "T2w"]

# Spatial Decomposition Strategy
# Relative offsets from the Brain Center of Mass (CoM) along the Z-axis
SPATIAL_OFFSETS = {
    "lower": -0.1,  # Expert A: -10% depth relative to CoM
    "center": 0.0,  # Expert B: Brain CoM
    "upper": 0.1,  # Expert C: +10% depth relative to CoM
}

# Data Loading
NUM_WORKERS = 4
PIN_MEMORY = True

# =============================================================================
# TRAINING HYPERPARAMETERS
# =============================================================================

SEED = 42
BATCH_SIZE = 32
EPOCHS = 20
LEARNING_RATE = 1e-4
WEIGHT_DECAY = 1e-2  # Aggressive regularization for small dataset
DROPOUT = 0.3  # Dropout rate for the classifier head
NUM_FOLDS = 5  # Cross-validation folds
PATIENCE = 5  # Early stopping patience

# Device Configuration
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

# =============================================================================
# UTILITY FUNCTIONS
# =============================================================================


def setup_reproducibility(seed=SEED):
    """
    Sets random seeds for Python, NumPy, and PyTorch to ensure reproducible results.
    """
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)

    # Deterministic operations usually come at a performance cost
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False

    # Set environment variable for hash seed
    os.environ["PYTHONHASHSEED"] = str(seed)


def create_directories():
    """
    Creates necessary working directories for caching, models, and submissions.
    """
    dirs = [WORKING_DIR, CACHE_DIR, MODEL_SAVE_DIR, SUBMISSION_DIR]
    for d in dirs:
        os.makedirs(d, exist_ok=True)
    print(f"Directories initialized at: {WORKING_DIR}")


# Initialize environment on import
setup_reproducibility()
create_directories()
